#define CLIENT_SECRET TEXT("<Your Client Secret>") // optional void MyClass::DoPatreonLogin() { // create an authentication action expecting a callback at http://localhost:8080/login UPerformAuthenticationAsyncAction* authAction = UPerformAuthenticationAsyncAction::PerformAuthenticationAsyncAction( this, // world context CLIENT_ID, CLIENT_SECRET // can be set to an empty string // callback route defaults to "/login" // callback port defaults to 8080 ); // register callbacks for results authAction->OnComplete.AddDynamic(this, &MyClass::OnAuthenticationComplete); authAction->OnFail.AddDynamic(this, &MyClass::OnAuthenticationFailed); // kick off action authAction->Activate();
} void MyClass::OnAuthenticationComplete(FAPITokenInfo TokenInfo) { // now that we have a token, we can use it to fetch information about the user who just logged in UGetPatreonUserInfoAsyncAction* getInfoAction = UGetPatreonUserInfoAsyncAction::GetPatreonUserInfoAsyncAction( this, // world context TokenInfo ); getInfoAction->OnComplete.AddDynamic(this, &MyClass::OnGetUserInfoComplete); getInfoAction->OnFail.AddDynamic(this, &MyClass::OnGetUserInfoFail); getInfoAction->Activate();
} void MyClass::OnAuthenticationFailed() { UE_LOG(LogTemp, Error, TEXT("Patreon authentication failed: The user may have denied the request for their data") );
} void MyClass::OnGetUserInfoComplete(FPatreonUserInfo UserInfo) { // now that we have the user's information, // we can check if they have pledged to a tier with unlockable content if (UserInfo.HasTier("Special Tier")) { UnlockSecretConent(); } else { // suggest the user should pledge to the Special Tier ;) }
} void MyClass::OnGetUserInfoFail() { UE_LOG(LogTemp, Error, TEXT("Fetching user info from Patreon API failed: Was the access token invalid?") );
} For any questions, help, suggestions or feature requests, please feel free to contact me at nbpsup@gmail.com

